FORBIDDEN_BACKUP_MANIFEST_SENSITIVE_MARKERS = [
    "backup-token-must-not-leak",
    "backup-client-secret-must-not-leak",
    "authorization: bearer backup-must-not-leak",
    "backup-headers-must-not-leak",
    "backup-signature-must-not-leak",
    "backup-bcrypt-must-not-leak",
    "backup-raw-response-must-not-leak",
    "channel-500000000000",
    "order-202607030001",
    "product-order-202607030001",
    "backup-buyer-name-must-not-leak",
    "010-1111-2222",
    "backup-address-must-not-leak",
    "zip-12345",
]

FORBIDDEN_TIME_PATTERNS = {
    "datetime.utcnow(": "use app.core.timezone.get_utc_now()",
    "date.today(": "use app.core.timezone.get_business_date() for business dates",
}


def _normalize_audit_key(value: str) -> str:
    return "".join(char for char in value.lower() if char.isalnum())


def _operation_audit_forbidden_key_name(key: str) -> str | None:
    normalized = _normalize_audit_key(key)
    if normalized in {"rawresponsesaved", "secretssaved", "privacyfieldsredacted"}:
        return None
    if normalized.endswith("hash"):
        return None
    exact_forbidden = {
        "accesstoken",
        "authorization",
        "bcrypt",
        "buyerfullname",
        "buyername",
        "buyerphone",
        "channelno",
        "clientsecret",
        "detailedaddress",
        "headers",
        "orderid",
        "productorderid",
        "rawdata",
        "rawrequest",
        "rawresponse",
        "receiverfullname",
        "receivername",
        "receiverphone",
        "refreshtoken",
        "requestheaders",
        "responseheaders",
        "signature",
        "token",
        "zipcode",
    }
    if normalized in exact_forbidden:
        return normalized
    if any(part in normalized for part in ["token", "authorization", "headers", "signature", "bcrypt", "clientsecret"]):
        return normalized
    if any(part in normalized for part in ["rawresponse", "rawrequest", "rawdata"]):
        return normalized
    if ("orderid" in normalized or "productorderid" in normalized) and not normalized.endswith("hash"):
        return normalized
    if any(part in normalized for part in ["buyer", "receiver", "phone", "address", "zipcode"]):
        return normalized
    return None


def _operation_audit_sensitive_fields(payload) -> list[str]:
    forbidden: set[str] = set()

    def walk(value, path: str = "") -> None:
        if isinstance(value, dict):
            for key, nested in value.items():
                key_name = str(key)
                forbidden_key = _operation_audit_forbidden_key_name(key_name)
                if forbidden_key:
                    forbidden.add(forbidden_key)
                    continue
                walk(nested, f"{path}.{key_name}" if path else key_name)
            return
        if isinstance(value, (list, tuple, set)):
            for item in value:
                walk(item, path)
            return
        if isinstance(value, str):
            lowered = value.lower()
            for marker in FORBIDDEN_OPERATION_AUDIT_SENSITIVE_MARKERS:
                if marker in lowered:
                    forbidden.add("sensitive_value")

    walk(payload)
    return sorted(forbidden)


def _operation_audit_valid_sha256(value: str | None) -> bool:
    if value is None:
        return True
    return len(value) == 64 and all(char in "0123456789abcdef" for char in value)


def _json_for_audit(value):
    if value is None:
        return None
    return json.dumps(value, ensure_ascii=False, sort_keys=True)


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _backup_manifest_sensitive_fields(manifest: dict) -> list[str]:
    forbidden = set(_operation_audit_sensitive_fields(manifest))
    manifest_text = json.dumps(manifest, ensure_ascii=False, default=str).lower()
    for marker in FORBIDDEN_BACKUP_MANIFEST_SENSITIVE_MARKERS:
        if marker in manifest_text:
            forbidden.add("sensitive_value")
    return sorted(forbidden)


def _validate_backup_manifest_safe_inputs(inputs: dict) -> dict:
    result = {
        "phase": "ERP-Backup-1E",
        "status": "backup_manifest_inputs_valid",
        "manifest_written": False,
        "real_database_touched": False,
        "real_backup_created": False,
        "real_restore_executed": False,
        "backup_deleted": False,
    }
    required = {
        "phase",
        "operation_type",
        "source_db_path",
        "backup_path",
        "backup_root",
        "created_by_actor_type",
        "created_by_actor_label",
        "retention_class",
        "retention_reason",
    }
    missing = sorted(required - set(inputs))
    if missing:
        result.update({
            "status": "backup_manifest_blocked",
            "skip_reason": "missing_manifest_inputs",
            "missing_manifest_inputs": missing,
        })
        return result
    if inputs.get("retention_class") not in ALLOWED_BACKUP_RETENTION_CLASSES:
        result.update({
            "status": "backup_manifest_blocked",
            "skip_reason": "invalid_retention_class",
        })
        return result
    if _backup_manifest_sensitive_fields(inputs):
        result.update({
            "status": "backup_manifest_blocked",
            "skip_reason": "manifest_sensitive_field_blocked",
        })
        return result

    source_path = Path(inputs["source_db_path"]).resolve()
    backup_path = Path(inputs["backup_path"]).resolve()
    backup_root = Path(inputs["backup_root"]).resolve()
    production_db_path = (BACKEND_DIR / "codex1.db").resolve()
    if source_path == production_db_path:
        result.update({
            "status": "backup_manifest_blocked",
            "skip_reason": "production_source_not_allowed_in_mock_gate",
        })
        return result
    if not source_path.exists():
        result.update({
            "status": "backup_manifest_blocked",
            "skip_reason": "source_db_missing",
        })
        return result
    if not backup_path.exists():
        result.update({
            "status": "backup_manifest_blocked",
            "skip_reason": "backup_file_missing",
        })
        return result
    try:
        backup_path.relative_to(backup_root)
    except ValueError:
        result.update({
            "status": "backup_manifest_blocked",
            "skip_reason": "backup_path_outside_approved_root",
        })
        return result
    return result


def _retention_until_for_class(created_at: datetime, retention_class: str) -> str | None:
    days = RETENTION_DAYS_BY_CLASS.get(retention_class)
    if days is None:
        return None
    return (created_at + timedelta(days=days)).isoformat()


def _collect_sqlite_counts_and_metadata(db_path: Path) -> tuple[dict[str, int], dict[str, int | str]]:
    with sqlite3.connect(db_path) as conn:
        integrity = conn.execute("PRAGMA integrity_check").fetchone()[0]
        page_count = conn.execute("PRAGMA page_count").fetchone()[0]
        page_size = conn.execute("PRAGMA page_size").fetchone()[0]
        table_names = {
            row[0]
            for row in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
        }
        count_tables = [
            "stores",
            "products",
            "orders",
            "sync_logs",
            "api_capability_test_results",
            "order_status_events",
            "operation_audit_logs",
        ]
        counts = {}
        for table_name in count_tables:
            if table_name in table_names:
                counts[table_name] = conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0]
            else:
                counts[table_name] = 0
        if "api_capability_test_results" in table_names:
            counts["tested_success_store8"] = conn.execute(
                "SELECT COUNT(*) FROM api_capability_test_results WHERE store_id=8 AND test_status='tested_success'"
            ).fetchone()[0]
        else:
            counts["tested_success_store8"] = 0
    return counts, {
        "sqlite_integrity_check": integrity,
        "sqlite_page_count": page_count,
        "sqlite_page_size": page_size,
    }


def _write_backup_manifest_mock_gate(inputs: dict) -> dict:
    validation = _validate_backup_manifest_safe_inputs(inputs)
    if validation["status"] != "backup_manifest_inputs_valid":
        return validation

    source_path = Path(inputs["source_db_path"]).resolve()
    backup_path = Path(inputs["backup_path"]).resolve()
    manifest_path = backup_path.with_suffix(backup_path.suffix + ".manifest.json")
    temp_manifest_path = backup_path.with_suffix(backup_path.suffix + ".manifest.json.tmp")
    if manifest_path.exists():
        return {
            "phase": "ERP-Backup-1E",
            "status": "backup_manifest_blocked",
            "skip_reason": "manifest_already_exists",
            "manifest_written": False,
            "real_database_touched": False,
            "real_backup_created": False,
            "real_restore_executed": False,
            "backup_deleted": False,
        }

    created_at = datetime.now(timezone.utc)
    retention_class = inputs["retention_class"]
    counts, sqlite_meta = _collect_sqlite_counts_and_metadata(backup_path)
    manifest = {
        "manifest_version": "backup-manifest-v1",
        "backup_id": inputs.get("backup_id") or f"backup-{backup_path.stem}",
        "phase": inputs["phase"],
        "operation_type": inputs["operation_type"],
        "created_at": created_at.isoformat(),
        "created_by_actor_type": inputs["created_by_actor_type"],
        "created_by_actor_label": inputs["created_by_actor_label"],
        "source_db_path": source_path.as_posix(),
        "backup_path": backup_path.as_posix(),
        "backup_sha256": _sha256_file(backup_path),
        "backup_size_bytes": backup_path.stat().st_size,
        "backup_method": inputs.get("backup_method", "mock_fixture_copy"),
        "sqlite_page_count": sqlite_meta["sqlite_page_count"],
        "sqlite_page_size": sqlite_meta["sqlite_page_size"],
        "sqlite_integrity_check": sqlite_meta["sqlite_integrity_check"],
        "git_commit_codex1": inputs.get("git_commit_codex1", "0" * 40),
        "git_commit_codex2": inputs.get("git_commit_codex2", "1" * 40),
        "baseline_counts": counts,
        "related_store_ids": inputs.get("related_store_ids", []),
        "related_platforms": inputs.get("related_platforms", []),
        "related_safe_hashes": inputs.get("related_safe_hashes", []),
        "retention_class": retention_class,
        "retention_reason": inputs["retention_reason"],
        "retention_until": _retention_until_for_class(created_at, retention_class),
        "legal_hold": bool(inputs.get("legal_hold", False)),
        "protected_from_auto_delete": retention_class in {
            "pre_write",
            "pre_migration",
            "pre_restore",
            "incident_response",
        } or bool(inputs.get("operation_audit_correlation_id")),
        "restore_drill_status": "pending",
        "last_restore_drill_at": None,
        "sensitive_scan_passed": True,
        "raw_response_saved": False,
        "secrets_saved": False,
        "privacy_fields_redacted": True,
        "operation_audit_correlation_id": inputs.get("operation_audit_correlation_id"),
        "notes": inputs.get("notes", "Temporary backup manifest mock gate only."),
    }
    forbidden_fields = _backup_manifest_sensitive_fields(manifest)
    if forbidden_fields:
        return {
            "phase": "ERP-Backup-1E",
            "status": "backup_manifest_blocked",
            "skip_reason": "manifest_sensitive_field_blocked",
            "forbidden_field_names": forbidden_fields,
            "manifest_written": False,
            "real_database_touched": False,
            "real_backup_created": False,
            "real_restore_executed": False,
            "backup_deleted": False,
        }
    if sqlite_meta["sqlite_integrity_check"] != "ok":
        return {
            "phase": "ERP-Backup-1E",
            "status": "backup_manifest_blocked",
            "skip_reason": "sqlite_integrity_check_failed",
            "manifest_written": False,
            "real_database_touched": False,
            "real_backup_created": False,
            "real_restore_executed": False,
            "backup_deleted": False,
        }

    temp_manifest_path.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True),
        encoding="utf-8",
    )
    loaded = json.loads(temp_manifest_path.read_text(encoding="utf-8"))
    missing = sorted(REQUIRED_BACKUP_MANIFEST_FIELDS - set(loaded))
    if missing:
        temp_manifest_path.unlink(missing_ok=True)
        return {
            "phase": "ERP-Backup-1E",
            "status": "backup_manifest_blocked",
            "skip_reason": "missing_manifest_fields",
            "missing_manifest_fields": missing,
            "manifest_written": False,
            "real_database_touched": False,
            "real_backup_created": False,
            "real_restore_executed": False,
            "backup_deleted": False,
        }
    temp_manifest_path.replace(manifest_path)
    return {
        "phase": "ERP-Backup-1E",
        "status": "backup_manifest_written",
        "manifest_written": True,
        "manifest_path": manifest_path.as_posix(),
        "backup_path": backup_path.as_posix(),
        "backup_sha256": manifest["backup_sha256"],
        "backup_size_bytes": manifest["backup_size_bytes"],
        "baseline_counts": manifest["baseline_counts"],
        "sqlite_integrity_check": manifest["sqlite_integrity_check"],
        "protected_from_auto_delete": manifest["protected_from_auto_delete"],
        "retention_class": manifest["retention_class"],
        "real_database_touched": False,
        "real_backup_created": False,
        "real_restore_executed": False,
        "backup_deleted": False,
        "raw_response_saved": False,
        "secrets_saved": False,
        "privacy_fields_redacted": True,
    }


def _validate_backup_manifest_for_restore_dry_run(manifest: dict, backup_path: Path) -> dict:
    result = {
        "phase": "ERP-Backup-1C",
        "status": "restore_dry_run_manifest_valid",
        "safe_to_restore_to_temp": True,
        "real_database_touched": False,
        "real_restore_executed": False,
    }
    missing = sorted(REQUIRED_BACKUP_MANIFEST_FIELDS - set(manifest))
    if missing:
        result.update({
            "status": "restore_dry_run_blocked",
            "skip_reason": "missing_manifest_fields",
            "missing_manifest_fields": missing,
            "safe_to_restore_to_temp": False,
        })
        return result
    if manifest.get("retention_class") not in ALLOWED_BACKUP_RETENTION_CLASSES:
        result.update({
            "status": "restore_dry_run_blocked",
            "skip_reason": "invalid_retention_class",
            "safe_to_restore_to_temp": False,
        })
        return result
    if not _operation_audit_valid_sha256(manifest.get("backup_sha256")):
        result.update({
            "status": "restore_dry_run_blocked",
            "skip_reason": "invalid_backup_sha256_format",
            "safe_to_restore_to_temp": False,
        })
        return result
    if manifest.get("raw_response_saved") is not False or manifest.get("secrets_saved") is not False:
        result.update({
            "status": "restore_dry_run_blocked",
            "skip_reason": "unsafe_manifest_saved_flags",
            "safe_to_restore_to_temp": False,
        })
        return result
    if manifest.get("privacy_fields_redacted") is not True or manifest.get("sensitive_scan_passed") is not True:
        result.update({
            "status": "restore_dry_run_blocked",
            "skip_reason": "manifest_safety_flags_failed",
            "safe_to_restore_to_temp": False,
        })
        return result
    forbidden_fields = _backup_manifest_sensitive_fields(manifest)
    if forbidden_fields:
        result.update({
            "status": "restore_dry_run_blocked",
            "skip_reason": "manifest_sensitive_field_blocked",
            "forbidden_field_names": forbidden_fields,
            "safe_to_restore_to_temp": False,
        })
        return result
    if not backup_path.exists():
        result.update({
            "status": "restore_dry_run_blocked",
            "skip_reason": "backup_file_missing",
            "safe_to_restore_to_temp": False,
        })
        return result
    if backup_path.stat().st_size != int(manifest["backup_size_bytes"]):
        result.update({
            "status": "restore_dry_run_blocked",
            "skip_reason": "backup_size_mismatch",
            "safe_to_restore_to_temp": False,
        })
        return result
    actual_sha = _sha256_file(backup_path)
    if actual_sha != manifest["backup_sha256"]:
        result.update({
            "status": "restore_dry_run_blocked",
            "skip_reason": "backup_sha256_mismatch",
            "safe_to_restore_to_temp": False,
        })
        return result
    return result


def _run_sqlite_restore_dry_run(manifest: dict, backup_path: Path, restore_path: Path) -> dict:
    production_db_path = (BACKEND_DIR / "codex1.db").resolve()
    if restore_path.resolve() == production_db_path:
        return {
            "phase": "ERP-Backup-1C",
            "status": "restore_dry_run_blocked",
            "skip_reason": "restore_target_is_production_db",
            "safe_to_restore_to_temp": False,
            "real_database_touched": False,
            "real_restore_executed": False,
        }
    manifest_gate = _validate_backup_manifest_for_restore_dry_run(manifest, backup_path)
    if manifest_gate["status"] != "restore_dry_run_manifest_valid":
        return manifest_gate

    restore_path.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(backup_path, restore_path)
    restored_sha = _sha256_file(restore_path)
    if restored_sha != manifest["backup_sha256"]:
        return {
            "phase": "ERP-Backup-1C",
            "status": "restore_dry_run_blocked",
            "skip_reason": "restored_copy_sha256_mismatch",
            "safe_to_restore_to_temp": False,
            "real_database_touched": False,
            "real_restore_executed": False,
        }

    with sqlite3.connect(restore_path) as conn:
        integrity = conn.execute("PRAGMA integrity_check").fetchone()[0]
        tables = {
            row[0]
            for row in conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
        }
        observed_counts = {
            table_name: conn.execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0]
            for table_name in manifest["baseline_counts"]
        }
    if integrity != "ok":
        return {
            "phase": "ERP-Backup-1C",
            "status": "restore_dry_run_blocked",
            "skip_reason": "sqlite_integrity_check_failed",
            "integrity_check": integrity,
            "safe_to_restore_to_temp": False,
            "real_database_touched": False,
            "real_restore_executed": False,
        }
    missing_tables = sorted(set(manifest["baseline_counts"]) - tables)
    if missing_tables:
        return {
            "phase": "ERP-Backup-1C",
            "status": "restore_dry_run_blocked",
            "skip_reason": "restore_missing_expected_tables",
            "missing_tables": missing_tables,
            "safe_to_restore_to_temp": False,
            "real_database_touched": False,
            "real_restore_executed": False,
        }
    if observed_counts != manifest["baseline_counts"]:
        return {
            "phase": "ERP-Backup-1C",
            "status": "restore_dry_run_blocked",
            "skip_reason": "restore_count_mismatch",
            "observed_counts": observed_counts,
            "expected_counts": manifest["baseline_counts"],
            "safe_to_restore_to_temp": False,
            "real_database_touched": False,
            "real_restore_executed": False,
        }

    return {
        "phase": "ERP-Backup-1C",
        "status": "restore_dry_run_verified",
        "safe_to_restore_to_temp": True,
        "real_database_touched": False,
        "real_restore_executed": False,
        "restore_target": "temporary_sqlite_fixture",
        "integrity_check": integrity,
        "observed_counts": observed_counts,
        "backup_sha256_verified": True,
        "restored_copy_sha256_verified": True,
        "raw_response_saved": False,
        "secrets_saved": False,
        "privacy_fields_redacted": True,
    }


def _operation_audit_mock_write_gate(db, audit_row: dict, *, write_enabled: bool, manual_approval: bool) -> dict:
    from sqlalchemy import text

    result = {
        "phase": "ERP-Audit-1C",
        "status": "audit_write_not_requested",
        "audit_rows_written": False,
        "rows_written": 0,
        "real_schema_changed": False,
        "real_database_written": False,
        "sync_log_written": False,
        "products_written": False,
        "orders_written": False,
        "capability_tested_success_written": False,
        "raw_response_saved": False,
        "secrets_saved": False,
        "privacy_fields_redacted": True,
        "formal_sync_open": False,
    }
    if not write_enabled:
        return result
    if not manual_approval:
        result.update({
            "status": "audit_write_blocked",
            "skip_reason": "manual_approval_required",
        })
        return result

    required_fields = ["created_at", "updated_at", "actor_type", "action", "correlation_id", "status"]
    missing_required = [
        field
        for field in required_fields
        if not str(audit_row.get(field, "")).strip()
    ]
    if missing_required:
        result.update({
            "status": "audit_write_blocked",
            "skip_reason": "missing_required_fields",
            "missing_required_fields": missing_required,
        })
        return result

    for sha_field in ["backup_sha256", "restore_source_sha256"]:
        if not _operation_audit_valid_sha256(audit_row.get(sha_field)):
            result.update({
                "status": "audit_write_blocked",
                "skip_reason": "invalid_sha256",
                "invalid_sha256_fields": [sha_field],
            })
            return result

    if audit_row.get("raw_response_saved") is not False or audit_row.get("secrets_saved") is not False:
        result.update({
            "status": "audit_write_blocked",
            "skip_reason": "unsafe_saved_flags",
        })
        return result
    if audit_row.get("privacy_fields_redacted") is not True:
        result.update({
            "status": "audit_write_blocked",
            "skip_reason": "privacy_fields_not_redacted",
        })
        return result
    if audit_row.get("status") != "blocked" and audit_row.get("sensitive_scan_passed") is not True:
        result.update({
            "status": "audit_write_blocked",
            "skip_reason": "sensitive_scan_not_passed",
        })
        return result

    forbidden_fields = _operation_audit_sensitive_fields(audit_row)
    if forbidden_fields:
        result.update({
            "status": "audit_write_blocked",
            "skip_reason": "audit_sensitive_field_blocked",
            "forbidden_field_names": forbidden_fields,
        })
        return result

    insert_sql = text("""
        INSERT INTO operation_audit_logs (
            created_at,
            updated_at,
            store_id,
            platform,
            environment,
            actor_type,
            actor_id,
            actor_label,
            actor_role,
            action,
            operation_phase,
            correlation_id,
            request_id,
            status,
            reason_code,
            target_type,
            target_id,
            target_hash,
            target_label,
            changed_field_names,
            before_summary,
            after_summary,
            counts_summary,
            safety_flags,
            backup_path,
            backup_sha256,
            restore_source_path,
            restore_source_sha256,
            sensitive_scan_passed,
            raw_response_saved,
            secrets_saved,
            privacy_fields_redacted,
            notes
        ) VALUES (
            :created_at,
            :updated_at,
            :store_id,
            :platform,
            :environment,
            :actor_type,
            :actor_id,
            :actor_label,
            :actor_role,
            :action,
            :operation_phase,
            :correlation_id,
            :request_id,
            :status,
            :reason_code,
            :target_type,
            :target_id,
            :target_hash,
            :target_label,
            :changed_field_names,
            :before_summary,
            :after_summary,
            :counts_summary,
            :safety_flags,
            :backup_path,
            :backup_sha256,
            :restore_source_path,
            :restore_source_sha256,
            :sensitive_scan_passed,
            :raw_response_saved,
            :secrets_saved,
            :privacy_fields_redacted,
            :notes
        )
    """)
    params = {
        "created_at": audit_row["created_at"],
        "updated_at": audit_row["updated_at"],
        "store_id": audit_row.get("store_id"),
        "platform": audit_row.get("platform"),
        "environment": audit_row.get("environment", "local"),
        "actor_type": audit_row["actor_type"],
        "actor_id": audit_row.get("actor_id"),
        "actor_label": audit_row.get("actor_label"),
        "actor_role": audit_row.get("actor_role"),
        "action": audit_row["action"],
        "operation_phase": audit_row.get("operation_phase"),
        "correlation_id": audit_row["correlation_id"],
        "request_id": audit_row.get("request_id"),
        "status": audit_row["status"],
        "reason_code": audit_row.get("reason_code"),
        "target_type": audit_row.get("target_type"),
        "target_id": audit_row.get("target_id"),
        "target_hash": audit_row.get("target_hash"),
        "target_label": audit_row.get("target_label"),
        "changed_field_names": _json_for_audit(audit_row.get("changed_field_names")),
        "before_summary": _json_for_audit(audit_row.get("before_summary")),
        "after_summary": _json_for_audit(audit_row.get("after_summary")),
        "counts_summary": _json_for_audit(audit_row.get("counts_summary")),
        "safety_flags": _json_for_audit(audit_row.get("safety_flags")),
        "backup_path": audit_row.get("backup_path"),
        "backup_sha256": audit_row.get("backup_sha256"),
        "restore_source_path": audit_row.get("restore_source_path"),
        "restore_source_sha256": audit_row.get("restore_source_sha256"),
        "sensitive_scan_passed": audit_row.get("sensitive_scan_passed", False),
        "raw_response_saved": audit_row.get("raw_response_saved", False),
        "secrets_saved": audit_row.get("secrets_saved", False),
        "privacy_fields_redacted": audit_row.get("privacy_fields_redacted", True),
        "notes": audit_row.get("notes"),
    }
    cursor = db.execute(insert_sql, params)
    db.commit()
    result.update({
        "status": "audit_row_written",
        "audit_rows_written": True,
        "rows_written": 1,
        "audit_log_id": cursor.lastrowid,
    })
    return result


def run(command: list[str], cwd: Path = BACKEND_DIR, echo: bool = True) -> str:
    result = subprocess.run(
        command,
        cwd=cwd,
        text=True,
        encoding="utf-8",
        errors="replace",
        capture_output=True,
        check=False,
    )
    if echo and result.stdout:
        print(result.stdout, end="")
    if echo and result.stderr:
        print(result.stderr, end="", file=sys.stderr)
    if result.returncode != 0:
        raise RuntimeError(f"Command failed: {' '.join(command)}")
    return result.stdout


def verify_compile() -> None:
    run([PYTHON, "-m", "compileall", "-q", "app", "scripts"])
    print("compile: ok")


def verify_stage_scripts() -> None:
    for script in [
        "verify_stage_1b.py",
        "verify_stage_1c.py",
        "verify_stage_1d.py",
        "verify_stage_1e.py",
        "verify_stage_1f.py",
        "verify_pxg_naver_readonly_persistence.py",
        "verify_pxg_naver_readonly_activation.py",
        "verify_pxg_naver_readonly_retention_cleanup.py",
        "verify_production_sessions.py",
    ]:
        print(f"running {script}")
        run([PYTHON, f"scripts/{script}"])
    print("stage scripts: ok")


def verify_openapi() -> None:
    from fastapi.testclient import TestClient

    from app.main import app

    with TestClient(app) as client:
        health = client.get("/api/v1/health")
        assert health.status_code == 200, health.text
        docs = client.get("/docs")
        assert docs.status_code == 200, docs.text[:100]
        openapi = client.get("/openapi.json")
        assert openapi.status_code == 200, openapi.text[:100]
        openapi_json = openapi.json()
        paths = set(openapi_json["paths"].keys())

    missing = sorted(EXPECTED_API_PATHS - paths)
    assert not missing, f"Missing OpenAPI paths: {missing}"
    assert "/api/v1/credentials/{credential_id}/decrypt" not in paths
