def verify_backup_report_readonly_local_api() -> None:
    from fastapi.testclient import TestClient

    from app.main import app

    production_db_path = BACKEND_DIR / "codex1.db"
    production_before = None
    if production_db_path.exists():
        production_before = {
            "size": production_db_path.stat().st_size,
            "sha256": _sha256_file(production_db_path),
        }

    with TestClient(app) as client:
        report_response = client.get("/api/v1/backups/local-report", params={"limit": 10})
        assert report_response.status_code == 200, report_response.text
        report_payload = report_response.json()["data"]
        assert report_payload["phase"] == "ERP-Backup-1L", report_payload
        assert report_payload["status"] in {"backup_report_ready", "backup_report_empty"}, report_payload
        assert report_payload["backup_report_readonly"] is True, report_payload
        assert report_payload["public_endpoint_enabled"] is True, report_payload
        assert report_payload["backup_deleted"] is False, report_payload
        assert report_payload["real_restore_executed"] is False, report_payload
        assert report_payload["production_db_touched"] is False, report_payload
        assert report_payload["rows_written"] == 0, report_payload
        assert report_payload["raw_response_saved"] is False, report_payload
        assert report_payload["secrets_saved"] is False, report_payload
        assert report_payload["privacy_fields_redacted"] is True, report_payload
        assert report_payload["formal_sync_open"] is False, report_payload
        assert report_payload["platform_writes_enabled"] is False, report_payload
        assert "备份" in report_payload["business_message"], report_payload

        summary_response = client.get("/api/v1/backups/local-report/summary", params={"limit": 10})
        assert summary_response.status_code == 200, summary_response.text
        summary_payload = summary_response.json()["data"]
        assert summary_payload["phase"] == "ERP-Backup-1L", summary_payload
        assert summary_payload["status"] == "backup_summary_success", summary_payload
        assert summary_payload["backup_report_readonly"] is True, summary_payload
        assert summary_payload["public_endpoint_enabled"] is True, summary_payload
        assert summary_payload["backup_deleted"] is False, summary_payload
        assert summary_payload["real_restore_executed"] is False, summary_payload
        assert summary_payload["production_db_touched"] is False, summary_payload
        assert summary_payload["rows_written"] == 0, summary_payload
        assert summary_payload["raw_response_saved"] is False, summary_payload
        assert summary_payload["secrets_saved"] is False, summary_payload
        assert summary_payload["privacy_fields_redacted"] is True, summary_payload
        assert summary_payload["formal_sync_open"] is False, summary_payload
        assert summary_payload["platform_writes_enabled"] is False, summary_payload

        unsupported = client.get("/api/v1/backups/local-report", params={"backup_root": "C:/not-allowed"})
        assert unsupported.status_code == 400, unsupported.text
        unsupported_text = json.dumps(unsupported.json(), ensure_ascii=False).lower()
        assert "c:/not-allowed" not in unsupported_text, unsupported_text
        assert "backup_root" not in unsupported_text, unsupported_text

        post_response = client.post("/api/v1/backups/local-report")
        delete_response = client.delete("/api/v1/backups/local-report")
        assert post_response.status_code == 405, post_response.text
        assert delete_response.status_code == 405, delete_response.text

        serialized = json.dumps(
            {
                "report": report_payload,
                "summary": summary_payload,
            },
            ensure_ascii=False,
            default=str,
        ).lower()
        for forbidden in FORBIDDEN_BACKUP_MANIFEST_SENSITIVE_MARKERS:
            assert forbidden not in serialized, serialized
        for forbidden in [
            "authorization",
            "client_secret",
            "headers",
            "signature",
            "bcrypt",
            "raw response",
            "productorderid",
            "buyername",
            "receiverphone",
            "zipcode",
        ]:
            assert forbidden not in serialized, serialized

    if production_before is not None:
        production_after = {
            "size": production_db_path.stat().st_size,
            "sha256": _sha256_file(production_db_path),
        }
        assert production_after == production_before, {
            "before": production_before,
            "after": production_after,
        }

    print("backup report readonly local API: ok")


def verify_shipping_mapping_schema_and_local_write() -> None:
    from fastapi.testclient import TestClient

    from app.main import app
    from app.database import SessionLocal
    from app.core.timezone import get_utc_now
    from app.models.order import Order
    from app.services.shipping_service import (
        evaluate_real_excel_generation_mock_gate,
        evaluate_tracking_import_xlsx_parser_mock,
        evaluate_tracking_number_import_mock_gate,
        generate_shipping_excel_local,
    )

    def build_tracking_import_xlsx_base64(rows: list[list[str]]) -> str:
        def column_name(index: int) -> str:
            name = ""
            while index:
                index, remainder = divmod(index - 1, 26)
                name = chr(65 + remainder) + name
            return name

        sheet_rows = []
        for row_index, row in enumerate(rows, start=1):
            cells = []
            for column_index, value in enumerate(row, start=1):
                cell_ref = f"{column_name(column_index)}{row_index}"
                cells.append(
                    f'<c r="{cell_ref}" t="inlineStr"><is><t>{escape(str(value or ""))}</t></is></c>'
                )
            sheet_rows.append(f'<row r="{row_index}">{"".join(cells)}</row>')
        sheet_xml = (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">'
            f'<sheetData>{"".join(sheet_rows)}</sheetData>'
            "</worksheet>"
        )
        buffer = BytesIO()
        with ZipFile(buffer, "w", ZIP_DEFLATED) as archive:
            archive.writestr("xl/worksheets/sheet1.xml", sheet_xml)
        return base64.b64encode(buffer.getvalue()).decode("ascii")

    def table_count(table_name: str, where_clause: str = "", params: tuple = ()) -> int:
        with sqlite3.connect(VERIFY_DB_PATH) as connection:
            return connection.execute(
                f"SELECT COUNT(*) FROM {table_name} {where_clause}",
                params,
            ).fetchone()[0]

    def shipping_counts(store_id: int) -> dict[str, int]:
        return {
            "orders": table_count("orders", "WHERE store_id=?", (store_id,)),
            "products": table_count("products", "WHERE store_id=?", (store_id,)),
            "sync_logs": table_count("sync_logs", "WHERE store_id=?", (store_id,)),
            "tested_success": table_count(
                "api_capability_test_results",
                "WHERE store_id=? AND test_status='tested_success'",
                (store_id,),
            ),
            "mappings": table_count("logistics_inventory_mappings", "WHERE store_id=?", (store_id,)),
            "inventory_items": table_count("logistics_inventory_items", "WHERE store_id=?", (store_id,)),
            "audit_logs": table_count(
                "operation_audit_logs",
                "WHERE store_id=? AND operation_phase='Shipping-2D'",
                (store_id,),
            ),
            "export_batches": table_count("shipping_export_batches", "WHERE store_id=?", (store_id,)),
            "export_rows": table_count("shipping_export_batch_rows", "WHERE store_id=?", (store_id,)),
            "export_audit_logs": table_count(
                "operation_audit_logs",
                "WHERE store_id=? AND operation_phase='Shipping-3D'",
                (store_id,),
            ),
            "tracking_import_batches": table_count(
                "shipping_tracking_import_batches",
                "WHERE store_id=?",
                (store_id,),
            ),
            "tracking_import_rows": table_count(
                "shipping_tracking_import_rows",
                "WHERE store_id=?",
                (store_id,),
            ),
            "tracking_import_audit_logs": table_count(
                "operation_audit_logs",
                "WHERE store_id=? AND operation_phase='Shipping-5D'",
                (store_id,),
            ),
            "order_status_events": table_count("order_status_events", "WHERE store_id=?", (store_id,)),
            "status_update_audit_logs": table_count(
                "operation_audit_logs",
                "WHERE store_id=? AND operation_phase='Shipping-8C'",
                (store_id,),
            ),
        }

    with sqlite3.connect(VERIFY_DB_PATH) as connection:
        tables = {
            row[0]
            for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
        }
        assert set(EXPECTED_SHIPPING_TABLE_COLUMNS) <= tables, tables
        for table_name, expected_columns in EXPECTED_SHIPPING_TABLE_COLUMNS.items():
            table_info = connection.execute(f"PRAGMA table_info({table_name})").fetchall()
            columns = {row[1] for row in table_info}
            assert expected_columns <= columns, (table_name, expected_columns - columns)
            forbidden_columns = sorted({column.lower() for column in columns} & FORBIDDEN_SHIPPING_COLUMNS)
            assert not forbidden_columns, (table_name, forbidden_columns)

        observed_indexes = {}
        for table_name in EXPECTED_SHIPPING_TABLE_COLUMNS:
            for row in connection.execute(f"PRAGMA index_list({table_name})").fetchall():
                observed_indexes[row[1]] = (table_name, bool(row[2]))
        for index_name, (expected_table, expected_columns, expected_unique) in EXPECTED_SHIPPING_INDEXES.items():
            assert index_name in observed_indexes, index_name
            observed_table, observed_unique = observed_indexes[index_name]
            assert observed_table == expected_table, (index_name, observed_table)
            assert observed_unique == expected_unique, (index_name, observed_unique)
            rows = connection.execute(f"PRAGMA index_info({index_name})").fetchall()
            assert [row[2] for row in rows] == expected_columns, (index_name, rows)

