def verify_docs_no_real_secrets() -> None:
    docs = list((BACKEND_DIR / "docs").glob("*.md")) + [BACKEND_DIR / "README.md"]
    for path in docs:
        text = path.read_text(encoding="utf-8")
        for pattern in FORBIDDEN_DOC_PATTERNS:
            assert pattern not in text, f"Forbidden pattern {pattern} found in {path}"
    print("docs secret scan: ok")


def verify_naver_product_local_sync_design_docs() -> None:
    readme = (BACKEND_DIR / "README.md").read_text(encoding="utf-8")
    api_contract = (BACKEND_DIR / "docs" / "API_CONTRACT.md").read_text(encoding="utf-8")
    combined = readme + "\n" + api_contract
    for required in [
        "Phase 6D-6J",
        "Phase 6D-6K",
        "Phase 6D-6M",
        "Phase 6D-6P",
        "Phase 6D-6R",
        "Phase 6D-6S",
        "Phase 6D-6T",
        "real_sync=true",
        "real_preview=true",
        "local_sync_result",
        "store_id=8",
        "credential_id=7",
        "page=1",
        "page=2",
        "size<=5",
        "sample_ids",
        "ready_for_local_sync",
        "single-channel",
        "channelProductNo",
        "productName",
        "source_type=naver_real_sync",
        "platform_origin_product_no",
        "platform_channel_product_id",
        "mapping_version=naver_product_v1",
        "synced_from=naver_product_preview",
        "raw_response_saved=false",
        "sync_type=naver_product_local_sync",
        "requested_size",
        "write_limit",
        "would_no_change",
        "would_refresh_only",
        "pagination_overlap_summary",
        "stop_and_review_pagination",
        "missing_optional_fields_block_write_approval",
        "missing_price_count",
        "missing_stock_count",
        "success_empty",
        "business_error_hint",
        "safe_keyword_flags",
        "ip_not_allowed",
        "credential_invalid",
        "permission_forbidden",
        "product_api_not_allowed",
        "unknown_forbidden",
        "backend/codex1.db",
        "ApiCapabilityTestResult tested_success",
    ]:
        assert required in combined, f"Missing Naver product local sync design marker: {required}"
    forbidden_claims = [
        "Phase 6D-6J writes products",
        "Phase 6D-6J writes SyncLog",
        "product sync is open",
        "batch product sync is open",
    ]
    for forbidden in forbidden_claims:
        assert forbidden not in combined, f"Forbidden 6D-6J sync-open wording found: {forbidden}"
    print("Naver product local sync design docs: ok")


def cleanup_verify_database() -> None:
    try:
        from app.database import engine

        engine.dispose()
    except Exception:
        pass

    removed: list[Path] = []
    retained: list[Path] = []
    for path in (VERIFY_DB_PATH, VERIFY_DB_PATH.with_suffix(VERIFY_DB_PATH.suffix + "-wal"), VERIFY_DB_PATH.with_suffix(VERIFY_DB_PATH.suffix + "-shm")):
        if not path.exists():
            continue
        try:
            path.unlink()
            removed.append(path)
        except PermissionError:
            retained.append(path)

    if removed:
        print("verify_all database removed: " + ", ".join(str(path) for path in removed))
    if retained:
        print("verify_all database retained outside project: " + ", ".join(str(path) for path in retained))


def main() -> None:
    if hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8")
    print(f"verify_all database: {VERIFY_DB_PATH}")
